/* --- Death screen --- */

.death-overlay {
  position: absolute;
  inset: 0;
  background: rgba(124, 10, 10, 0.5);
  z-index: 8;
  display: flex;
  align-items: center;
  justify-content: center;
}

.death-content {
  display: grid;
  gap: 14px;
  justify-items: center;
  text-align: center;
}

.death-title {
  font-size: 44px;
  font-weight: 700;
  color: var(--mc-text-light);
  text-shadow: 3px 3px 0 rgba(0, 0, 0, 0.55);
}

.death-sub {
  font-size: 15px;
  color: #f3dcdc;
  text-shadow: var(--mc-text-shadow);
}

.death-content .mc-button {
  min-width: 220px;
}

@media (max-width: 720px) {
  .hud-bottom {
    bottom: 4px;
  }

  .hotbar-slot {
    width: 38px;
    height: 38px;

