        <PauseMenu
          saveMessage={saveMessage}
          audioSettings={audioSettings}
          onAudioSettingsChange={updateAudioSettings}
          skinId={skinId}
          onSkinChange={updateSkin}
          onBack={resumeNow}
          onSave={saveNow}
          onLoad={loadNow}
          onReset={resetNow}
        />
      ) : null}

      <DeathScreen seconds={respawnSeconds} onRespawn={respawnNow} />

